import * as T from './vendor/three.module.js';
import {createNatureKit} from './nature.mjs';
import {targetObjects} from './target-games.mjs';
export function createTargetWorld(kind,person){
 const scene=new T.Scene();scene.background=new T.Color(kind==='snow'?'#bbd1d9':'#b9d2c9');scene.fog=new T.Fog(scene.background,50,220);scene.add(new T.HemisphereLight('#fff0d5','#617a70',2));const sun=new T.DirectionalLight('#fff0d7',2.2);sun.position.set(-15,25,20);scene.add(sun);
 const camera=new T.OrthographicCamera(-12,12,15,-1,.1,400);camera.position.set(0,7,24);camera.lookAt(0,7,0);const groups=new Map(),clickTargets=[],borrowed=[];const materials=new Map(),mat=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.88}));return materials.get(c);};
 function mesh(geo,color,x,y,z,p=scene,id=null){const o=new T.Mesh(geo,mat(color));o.position.set(x,y,z);p.add(o);if(id)o.userData.targetId=id;return o;}
 function ball(r,c,x,y,z,p,id,sx=1,sy=1,sz=1){const o=mesh(new T.SphereGeometry(r,16,12),c,x,y,z,p,id);o.scale.set(sx,sy,sz);return o;}
 function box(w,h,d,c,x,y,z,p,id){return mesh(new T.BoxGeometry(w,h,d),c,x,y,z,p,id);}
 function rod(a,b,r,c,p,id){const u=new T.Vector3(...a),v=new T.Vector3(...b),delta=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r,r,delta.length(),8),c,0,0,0,p,id);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return o;}
 function label(text,x,y,z,p=scene){const c=document.createElement('canvas');c.width=512;c.height=100;const ct=c.getContext('2d');ct.fillStyle='#fcf6e8';ct.fillRect(0,0,512,100);ct.fillStyle='#39584b';ct.font='bold 38px sans-serif';ct.textAlign='center';ct.fillText(text,256,66);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const m=new T.MeshBasicMaterial({map:tex,side:T.DoubleSide});const o=new T.Mesh(new T.PlaneGeometry(3.1,.6),m);o.position.set(x,y,z);p.add(o);return o;}
 const floor=mesh(new T.PlaneGeometry(120,100,40,30),kind==='snow'?'#e7ecec':'#8c9b78',0,-.05,-20);floor.rotation.x=-Math.PI/2;
 const nature=createNatureKit(scene,[],()=>.47,{flowerCount:0,grassCount:0});for(let i=0;i<24;i++){const side=i%2?1:-1;nature.tree(side*(12+i%4*2),-5-Math.floor(i/2)*2,.75+(i%3)*.12);}nature.finishTrees();nature.swissMountains();
 if(kind==='snow'){
  for(let i=0;i<4;i++){const g=new T.Group(),id='body'+i;scene.add(g);if(i<3){ball(1.2,'#eff1e9',0,1.2,0,g,id);ball(.93,'#e4ece9',0,3.05,0,g,id);ball(.68,'#f2f3e9',0,4.65,0,g,id);for(const x of[-.22,.22])ball(.065,'#3f4640',x,4.75,.63,g,id);const nose=mesh(new T.ConeGeometry(.11,.52,10),'#bd8049',0,4.56,.82,g,id);nose.rotation.x=Math.PI/2;for(const y of[2.7,3.1,3.5])ball(.08,'#505c53',0,y,.9,g,id);for(const side of[-1,1])rod([side*.65,3.3,0],[side*1.75,3.8,.1],.055,'#897051',g,id);}else{ball(1,'#9b7954',0,2.2,0,g,id,1.2,1.4,.65);for(const x of[-.6,.6])rod([x,.2,0],[x,1.6,0],.14,'#826448',g,id);rod([0,2.8,0],[0,4.2,0],.32,'#9b7954',g,id);ball(.6,'#b08b64',0,4.65,0,g,id,1,.85,.75);for(const side of[-1,1]){rod([side*.3,5,0],[side*.7,6,0],.06,'#6d5743',g,id);rod([side*.5,5.5,0],[side*1.1,5.7,0],.05,'#6d5743',g,id);}}
   const hat=new T.Group();g.add(hat);mesh(new T.CylinderGeometry(.8,.8,.10,24),i%2?'#5b7c8b':'#9b5b4f',0,5.3,0,hat,'hat'+i);mesh(new T.CylinderGeometry(.56,.64,.60,24),i%2?'#5b7c8b':'#9b5b4f',0,5.6,0,hat,'hat'+i);groups.set('hat'+i,{g,hat});clickTargets.push(g);
  }
  const cover=new T.Group();scene.add(cover);box(2.3,2.1,.16,'#a98b61',0,0,0,cover,'cover');for(const y of[-.65,0,.65])box(2.25,.04,.20,'#725e47',0,y,.02,cover,'cover');groups.set('cover',{g:cover});clickTargets.push(cover);
  for(let i=0;i<3;i++){const g=person.clone(true);g.scale.setScalar(i===2?2:2.5);g.traverse(o=>{if(o.isMesh)o.userData.targetId='person'+i;});scene.add(g);borrowed.push(g);const shield=label(i===2?'KIND · SCHÜTZEN':'NICHT TREFFEN',0,2.25,0,g);shield.scale.setScalar(.6);groups.set('person'+i,{g});clickTargets.push(g);}
 }else{
  for(let i=0;i<4;i++){const id=i===3?'white3':'bird'+i,g=new T.Group();scene.add(g);const white=i===3,color=white?'#f4f1e6':i%2?'#8c979c':'#8b795e';ball(.55,color,0,0,0,g,id,1.45,.75,.7);ball(.32,white?'#f4f1e6':i%2?'#747f89':'#517960',.65,.28,0,g,id);const bill=mesh(new T.ConeGeometry(.10,.38,10),'#bc9b55',.98,.22,0,g,id);bill.rotation.z=-Math.PI/2;const wings=[];for(const side of[-1,1]){const wing=ball(.5,white?'#e9e9df':color,0,.12,side*.35,g,id,1.1,.14,1.6);wings.push(wing);}const tail=box(.7,.13,.48,color,-.85,.05,0,g,id);tail.rotation.z=.15;if(white)label('WEISS · GESCHÜTZT',0,-1.0,.1,g);groups.set(id,{g,wings});clickTargets.push(g);}
 }
 const cross=new T.Group();scene.add(cross);const crossMat=new T.MeshBasicMaterial({color:'#f5d28e',depthTest:false});for(const [w,h]of [[.6,.045],[.045,.6]]){const m=new T.Mesh(new T.PlaneGeometry(w,h),crossMat);cross.add(m);m.renderOrder=20;}const projectile=ball(.13,'#fafbf4',0,0,5,scene);projectile.visible=false;
 return{scene,camera,groups,clickTargets,
 pickable(){const out=[];for(const root of clickTargets)root.traverse(o=>{if(!o.isMesh||!o.userData.targetId)return;for(let p=o;p;p=p.parent)if(!p.visible)return;out.push(o);});return out;},
 resize(aspect){const halfH=Math.max(8,12/aspect),halfW=halfH*aspect;camera.left=-halfW;camera.right=halfW;camera.top=halfH;camera.bottom=-halfH;camera.position.set(0,7,24);camera.lookAt(0,7,0);camera.updateProjectionMatrix();},
 sync(c){const list=targetObjects(c);for(const [id,item]of groups){const o=list.find(o=>o.id===id);if(id.startsWith('hat')){item.g.position.set(o.x,o.y-5.6,o.z);item.hat.visible=o.visible;}else{item.g.visible=!!o?.visible;if(o){item.g.position.set(o.x,id.startsWith('person')?1:o.y,o.z);if(item.wings)item.wings.forEach((w,i)=>w.rotation.x=Math.sin(c.time*12+i*Math.PI)*.55);}}}cross.position.set(c.aim.x,c.aim.y,6);projectile.visible=kind==='snow'&&c.cooldown>0;if(projectile.visible){const t=1-c.cooldown/.35;projectile.position.set(c.aim.x*t,1+(c.aim.y-1)*t+Math.sin(t*Math.PI),6*(1-t));}scene.updateMatrixWorld(true);camera.updateMatrixWorld();},
 dispose(){for(const g of borrowed){for(const o of [...g.children])if(o.geometry?.type==='PlaneGeometry'&&o.material?.map){o.geometry.dispose();o.material.map.dispose();o.material.dispose();}scene.remove(g);}const gs=new Set(),ms=new Set(),ts=new Set();scene.traverse(o=>{if(o.geometry)gs.add(o.geometry);if(o.material)ms.add(o.material);});gs.forEach(g=>g.dispose());ms.forEach(m=>{for(const v of Object.values(m))if(v?.isTexture)ts.add(v);m.dispose();});ts.forEach(t=>t.dispose());scene.clear();}
 };
}
